    private handlePaintReadyAction(): void {
        if (
            this.phase !== 'paint' ||
            !multiplayerClient.isConnected()
        ) {
            return;
        }

        const stateRole =
            multiplayerClient
                .getLocalPlayer()
                ?.role;

        const role =
            stateRole ??
            (
                this.networkPlayerManager
                    ?.isLocalHunter()
                    ? 'hunter'
                    : this.networkPlayerManager
                        ?.isLocalHider()
                        ? 'hider'
                        : undefined
            );

        if (role === 'hider') {
            /*
             * v0.10.10.240 READY INTENT LOCK:
             * Capture the user's tap as an immutable intent. During reconnect,
             * a delayed authoritative snapshot from the OLD session can briefly
             * report ready=false and overwrite this.localPaintReady. If retries
             * read the mutable UI flag, they accidentally send false and cancel
             * the READY tap. Every retry for this tap must send the captured value.
             */
            const desiredReady =
                !this.localPaintReady;

            this.localPaintReady =
                desiredReady;

            multiplayerClient
                .sendPaintReady(
                    desiredReady,
                );

            [120, 360, 800, 1600, 3200].forEach(
                (delay) => {
                    this.time.delayedCall(
                        delay,
                        () => {
                            if (this.phase !== 'paint') {
                                return;
                            }

                            multiplayerClient.sendPaintReady(
                                desiredReady,
                            );
                            multiplayerClient.requestPaintReadyState();
                        },
                    );
                },
            );

            this.time.delayedCall(
                80,
                () => {
                    if (
                        this.phase ===
                            'paint'
                    ) {
                        multiplayerClient
                            .requestPaintReadyState();
                    }
                },
            );
        } else if (
            role === 'hunter' &&
            this.allHidersPaintReady
        ) {
            multiplayerClient
                .sendEarlyStartHunt();
        }

        this.updatePaintReadyButton();
    }

    private createPaintReadyDomButton(): void {
        this.paintReadyDomButton
            ?.remove();

        const button =
            document.createElement(
                'button',
            );

        button.type =
            'button';
        button.className =
            'colorhunt-paint-ready-fixed';
        button.hidden =
            true;

        button.addEventListener(
            'pointerdown',
            (
                event,
            ) => {
                event.preventDefault();
                event.stopPropagation();
            },
        );

        button.addEventListener(
            'click',
            (
                event,
            ) => {
                event.preventDefault();
                event.stopPropagation();
                this.handlePaintReadyAction();
            },
        );

        document.body.appendChild(
            button,
        );

        this.paintReadyDomButton =
            button;
    }

    private destroyPaintReadyDomButton(): void {
        this.paintReadyDomButton
            ?.remove();

        this.paintReadyDomButton =
            undefined;
    }

